CREATE OR REPLACE PACKAGE BODY bench.b2 AS
  TYPE t_Rating_list IS TABLE OF t_rating INDEX BY PLS_INTEGER;

  FUNCTION run RETURN NUMBER IS
    l_t0 NUMBER;
    l_rows t_Rating_list;
    l_t1 NUMBER;
  BEGIN
    l_t0 := dbms_utility.get_time();
    select user_id, movie_id, rating, ts
      BULK COLLECT INTO l_rows
      FROM ml_ratings_src;
    FORALL i_r IN l_rows.FIRST .. l_rows.LAST
      insert into ml_ratings_b2(user_id, movie_id, rating, ts)
            values (l_rows(i_r).user_id, l_rows(i_r).movie_id, l_rows(i_r).rating, l_rows(i_r).ts);
    l_t1 := dbms_utility.get_time();
    RETURN ((l_t1 - l_t0) * 10);
  END run;
END b2;
